<?php

namespace App\Services;

class HardwareIntegrationService
{
    /**
     * Parse weight-embedded EAN-13 barcodes generated by electronic produce scales.
     * Standard supermarket format: 20AAAAAWWWWW[C]
     * Prefix (2 chars), PLU/Code (5 chars), Weight in Grams (5 chars), Checksum (1 char).
     */
    public function parseWeightBarcode(string $barcode, ?string $expectedPrefix = null): ?array
    {
        $barcode = trim($barcode);

        // Ensure 12 or 13 digits
        if (! preg_match('/^\d{12,13}$/', $barcode)) {
            return null;
        }

        $prefix = substr($barcode, 0, 2);
        $validPrefixes = $expectedPrefix ? [$expectedPrefix] : ['20', '02', '24'];

        if (! in_array($prefix, $validPrefixes, true)) {
            return null;
        }

        $pluCode = substr($barcode, 2, 5);
        $weightGrams = (int) substr($barcode, 7, 5);
        $weightKg = round($weightGrams / 1000, 3);
        $checksum = strlen($barcode) === 13 ? substr($barcode, 12, 1) : null;

        return [
            'type' => 'weight',
            'raw_barcode' => $barcode,
            'prefix' => $prefix,
            'plu_code' => $pluCode,
            'weight_grams' => $weightGrams,
            'weight_kg' => $weightKg,
            'unit' => 'kg',
            'checksum' => $checksum,
        ];
    }

    /**
     * Parse price-embedded EAN-13 barcodes generated by electronic produce scales.
     * Standard supermarket format: 21AAAAAPPPPP[C]
     * Prefix (2 chars), PLU/Code (5 chars), Price in cents/paisas (5 chars), Checksum (1 char).
     */
    public function parsePriceBarcode(string $barcode, ?string $expectedPrefix = null): ?array
    {
        $barcode = trim($barcode);

        if (! preg_match('/^\d{12,13}$/', $barcode)) {
            return null;
        }

        $prefix = substr($barcode, 0, 2);
        $validPrefixes = $expectedPrefix ? [$expectedPrefix] : ['21', '01'];

        if (! in_array($prefix, $validPrefixes, true)) {
            return null;
        }

        $pluCode = substr($barcode, 2, 5);
        $priceUnits = (int) substr($barcode, 7, 5);
        $totalPrice = round($priceUnits / 100, 2);
        $checksum = strlen($barcode) === 13 ? substr($barcode, 12, 1) : null;

        return [
            'type' => 'price',
            'raw_barcode' => $barcode,
            'prefix' => $prefix,
            'plu_code' => $pluCode,
            'price' => $totalPrice,
            'checksum' => $checksum,
        ];
    }

