            'align_center' => "\x1b\x61\x01",
            'align_right' => "\x1b\x61\x02",
            'bold_on' => "\x1b\x45\x01",
            'bold_off' => "\x1b\x45\x00",
            'double_height_on' => "\x1b\x21\x10",
            'double_width_on' => "\x1b\x21\x20",
            'normal_font' => "\x1b\x21\x00",
            'line_feed' => "\x0a",
